    assert Arrays.equals(solution.longestRepeating("abyzz", "aa", new int[]{2,1}), new int[]{2, 3});
    assert Arrays.equals(solution.longestRepeating("abcde", "ee", new int[]{2,4}), new int[]{1, 1});
    assert Arrays.equals(solution.longestRepeating("zzzzz", "abcd", new int[]{0,1,2,3}), new int[]{4, 3, 2, 1});
    assert Arrays.equals(solution.longestRepeating("babacc", "bcb", new int[]{1,3,3}), new int[]{3, 3, 4});
